mapper.select:
SELECT q.id, q.title, q.content, q.status, q.create_time, q.course_id, c.name AS courseName, qf.file_url FROM question q LEFT JOIN course c ON q.course_id = c.id LEFT JOIN question_file qf ON q.id = qf.question_id WHERE q.student_id = #{studentId}
AND (q.title LIKE concat('%', #{dto.keyword}, '%') OR q.content LIKE concat('%', #{dto.keyword}, '%'))
ORDER BY q.create_time DESC
